/* Pixel-themed number guessing game */
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --secondary: #0f3460;
  --text: #eaeaea;
  --accent: #f5c542;
  --border: #e94560;
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  background-image: 
    linear-gradient(45deg, #1a1a2e 25%, transparent 25%),
    linear-gradient(-45deg, #1a1a2e 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #1a1a2e 75%),
    linear-gradient(-45deg, transparent 75%, #1a1a2e 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
}

.game-container {
  width: 100%;
  max-width: 480px;
}

.game-card {
  background: var(--card-bg);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--secondary);
  padding: 2rem 1.5rem;
  text-align: center;
  image-rendering: pixelated;
}

h1 {
  font-size: 1.75rem;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 0.5rem;
  text-shadow: 2px 2px 0 var(--secondary);
}

.subtitle {
  font-size: 1rem;
  margin-bottom: 1.5rem;
  color: var(--text);
}

label {
  display: block;
  margin-bottom: 0.5rem;
  font-weight: bold;
  text-align: left;
}

.input-group {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

input[type="number"] {
  flex: 1;
  padding: 0.75rem;
  font-family: var(--font);
  font-size: 1.25rem;
  background: var(--bg);
  border: 3px solid var(--secondary);
  color: var(--text);
  outline: none;
  transition: border-color 0.2s;
  -moz-appearance: textfield;
}

input[type="number"]::-webkit-outer-spin-button,
input[type="number"]::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

input[type="number"]:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(245, 197, 66, 0.3);
}

button {
  font-family: var(--font);
  font-size: 1.125rem;
  font-weight: bold;
  padding: 0.75rem 1.25rem;
  background: var(--primary);
  color: var(--text);
  border: 3px solid var(--border);
  cursor: pointer;
  transition: all 0.1s;
  text-transform: uppercase;
  letter-spacing: 1px;
  box-shadow: 4px 4px 0 var(--secondary);
}

button:hover {
  background: #ff5a7a;
  transform: translate(-2px, -2px);
  box-shadow: 6px 6px 0 var(--secondary);
}

button:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 var(--secondary);
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.feedback {
  min-height: 3rem;
  margin: 1rem 0;
  padding: 0.75rem;
  font-size: 1.125rem;
  background: var(--bg);
  border: 2px dashed var(--secondary);
  display: flex;
  align-items: center;
  justify-content: center;
}

.feedback.success {
  border-color: var(--accent);
  color: var(--accent);
  animation: pulse 0.5s ease;
}

.feedback.error {
  border-color: var(--primary);
  color: var(--primary);
}

@keyframes pulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.05); }
  100% { transform: scale(1); }
}

.stats {
  margin: 1rem 0;
  font-size: 1.125rem;
}

#guess-count {
  color: var(--accent);
  font-weight: bold;
}

.new-game {
  background: var(--secondary);
  border-color: var(--accent);
  margin-top: 0.5rem;
}

.new-game:hover {
  background: #1a4a7a;
}

/* Responsive */
@media (max-width: 400px) {
  .game-card {
    padding: 1.5rem 1rem;
  }
  h1 {
    font-size: 1.5rem;
  }
  .input-group {
    flex-direction: column;
  }
  button {
    width: 100%;
  }
}

'use strict';

const state = {
  target: 0,
  guesses: 0,
  gameOver: false
};

const guessForm = document.getElementById('guess-form');
const guessInput = document.getElementById('guess-input');
const guessBtn = document.getElementById('guess-btn');
const feedback = document.getElementById('feedback');
const guessCount = document.getElementById('guess-count');
const newGameBtn = document.getElementById('new-game-btn');

function initGame() {
  state.target = Math.floor(Math.random() * 100) + 1;
  state.guesses = 0;
  state.gameOver = false;
  guessCount.textContent = '0';
  feedback.textContent = 'Enter a number and press Guess.';
  feedback.className = 'feedback';
  guessInput.value = '';
  guessInput.disabled = false;
  guessBtn.disabled = false;
  guessInput.focus();
}

function handleGuess(e) {
  e.preventDefault();
  if (state.gameOver) return;

  const raw = guessInput.value.trim();
  const num = Number(raw);

  if (raw === '' || !Number.isInteger(num) || num < 1 || num > 100) {
    feedback.textContent = 'Please enter a whole number between 1 and 100.';
    feedback.className = 'feedback error';
    return;
  }

  state.guesses++;
  guessCount.textContent = state.guesses;

  if (num === state.target) {
    feedback.textContent = `Correct! You guessed it in ${state.guesses} ${state.guesses === 1 ? 'guess' : 'guesses'}!`;
    feedback.className = 'feedback success';
    state.gameOver = true;
    guessInput.disabled = true;
    guessBtn.disabled = true;
  } else if (num < state.target) {
    feedback.textContent = 'Too low! Try a higher number.';
    feedback.className = 'feedback';
  } else {
    feedback.textContent = 'Too high! Try a lower number.';
    feedback.className = 'feedback';
  }

  guessInput.select();
}

guessForm.addEventListener('submit', handleGuess);
newGameBtn.addEventListener('click', initGame);

// Start game on load
initGame();
